import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Settings, ChevronRight, User, ClipboardList, Heart, Target, Bell, Moon, Globe, LogOut } from 'lucide-react';
import AppLayout from '../components/AppLayout';
import { useApp } from '../context/AppContext';
import { C } from '../components/UI';

function SettingsRow({ icon: Icon, label, value, onClick, danger }) {
  return (
    <div
      onClick={onClick}
      style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '13px 0', borderBottom: `1px solid ${C.border}`, cursor: onClick ? 'pointer' : 'default',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{
          width: 32, height: 32, borderRadius: 8,
          background: danger ? 'rgba(255,77,109,0.1)' : '#252525',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Icon size={16} color={danger ? '#ff4d6d' : '#888'} />
        </div>
        <span style={{ fontSize: 14, color: danger ? '#ff4d6d' : '#e0e0e0' }}>{label}</span>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        {value && <span style={{ fontSize: 12, color: '#555' }}>{value}</span>}
        {!danger && <ChevronRight size={14} color="#444" />}
      </div>
    </div>
  );
}

function Toggle({ on, onToggle }) {
  return (
    <div
      onClick={onToggle}
      style={{
        width: 42, height: 24, borderRadius: 12,
        background: on ? C.orange : '#333',
        position: 'relative', cursor: 'pointer', transition: 'background 0.2s',
      }}
    >
      <div style={{
        position: 'absolute', top: 3, left: on ? 21 : 3,
        width: 18, height: 18, borderRadius: '50%', background: '#fff',
        transition: 'left 0.2s',
      }} />
    </div>
  );
}

export default function ProfileScreen() {
  const navigate = useNavigate();
  const { user, setUser, darkMode, setDarkMode } = useApp();
  const name  = user?.name  || 'Guest User';
  const email = user?.email || 'guest@nutribite.com';

  function handleLogout() {
    setUser(null);
    navigate('/onboarding');
  }

  return (
    <AppLayout>
      <div style={{ padding: '20px 16px 0' }}>
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <div />
          <button style={{ background: 'none', border: 'none', color: '#ccc', cursor: 'pointer' }}>
            <Settings size={20} />
          </button>
        </div>

        {/* Avatar + info */}
        <div
          onClick={() => {}}
          style={{
            display: 'flex', alignItems: 'center', gap: 14,
            background: '#1e1e1e', borderRadius: 16, padding: 16,
            border: `1px solid ${C.border}`, marginBottom: 24, cursor: 'pointer',
          }}
        >
          <div style={{
            width: 52, height: 52, borderRadius: '50%',
            background: 'linear-gradient(135deg, #FF6B35, #FF8C5A)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 22, fontWeight: 800, color: '#fff', flexShrink: 0,
          }}>
            {name.charAt(0)}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: '#fff' }}>{name}</div>
            <div style={{ fontSize: 12, color: '#666' }}>{email}</div>
          </div>
          <ChevronRight size={18} color="#444" />
        </div>

        {/* Account Section */}
        <p style={{ fontSize: 12, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>Account</p>
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 20 }}>
          <SettingsRow icon={User}          label="Personal Information" onClick={() => {}} />
          <SettingsRow icon={ClipboardList} label="Dietary Preferences"  onClick={() => navigate('/preferences')} />
          <SettingsRow icon={Heart}         label="Medical Reports"       onClick={() => {}} />
          <SettingsRow icon={Target}        label="Health Goals"          onClick={() => navigate('/preferences')} />
        </div>

        {/* Preferences Section */}
        <p style={{ fontSize: 12, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>Preferences</p>
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 20 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0', borderBottom: `1px solid ${C.border}` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 32, height: 32, borderRadius: 8, background: '#252525', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Bell size={16} color="#888" />
              </div>
              <span style={{ fontSize: 14, color: '#e0e0e0' }}>Notification Settings</span>
            </div>
            <ChevronRight size={14} color="#444" />
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0', borderBottom: `1px solid ${C.border}` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 32, height: 32, borderRadius: 8, background: '#252525', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Moon size={16} color="#888" />
              </div>
              <span style={{ fontSize: 14, color: '#e0e0e0' }}>Dark Mode</span>
            </div>
            <Toggle on={darkMode} onToggle={() => setDarkMode(v => !v)} />
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 32, height: 32, borderRadius: 8, background: '#252525', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Globe size={16} color="#888" />
              </div>
              <span style={{ fontSize: 14, color: '#e0e0e0' }}>Language</span>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ fontSize: 12, color: '#555' }}>English</span>
              <ChevronRight size={14} color="#444" />
            </div>
          </div>
        </div>

        {/* Logout */}
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 16 }}>
          <div
            onClick={handleLogout}
            style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '14px 0', cursor: 'pointer', gap: 8 }}
          >
            <LogOut size={16} color="#ff4d6d" />
            <span style={{ color: '#ff4d6d', fontWeight: 700, fontSize: 14 }}>Log Out</span>
          </div>
        </div>

        <p style={{ textAlign: 'center', fontSize: 11, color: '#333', paddingBottom: 8 }}>NutriBite v1.0.0 MVP</p>
      </div>
    </AppLayout>
  );
}
